  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly attributes a positive outcome, action, or achievement to their own efforts, advocacy, or role in the legislative or executive process.",
    "clarification": "Credit-claiming is identified when a senator uses language such as 'I secured,' 'I helped,' 'I announced,' 'I played a key role,' or similar phrasing that directly links their personal or collective actions to a tangible result, funding allocation, or policy outcome. This includes taking credit for introducing, advocating for, or ensuring the passage of legislation, as well as securing funds, grants, or other resources for their constituents or state.",
    "positive_examples": [
